H.background();
const cx = H.W * 0.34, cy = H.H * 0.56, R = Math.min(H.W, H.H) * 0.30;
const A = t * 0.5;
const B = P.B * Math.PI / 180;
const cA = Math.cos(A), sA = Math.sin(A), cB = Math.cos(B), sB = Math.sin(B);
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 1.5 });
H.line(cx - R - 14, cy, cx + R + 14, cy, { color: H.colors.axis, width: 1 });
H.line(cx, cy - R - 14, cx, cy + R + 14, { color: H.colors.axis, width: 1 });
const ax = cx + R * cA, ay = cy - R * sA;
const bx = cx + R * cB, by = cy - R * sB;
H.line(cx, cy, ax, ay, { color: H.colors.accent, width: 2.5 });
H.line(cx, cy, bx, by, { color: H.colors.accent2, width: 2.5 });
const m = 26;
H.path([[cx + m, cy], [cx + m * Math.cos(B), cy - m * Math.sin(B)]], { color: H.colors.violet, width: 2 });
H.circle(ax, ay, 5, { fill: H.colors.accent });
H.circle(bx, by, 5, { fill: H.colors.accent2 });
H.text("A", ax + 8, ay, { color: H.colors.accent, size: 13 });
H.text("B", bx + 8, by + 4, { color: H.colors.accent2, size: 13 });
H.text("Sum & difference: cos(A - B) = cosA cosB + sinA sinB", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("cos(A - B) is the cosine of the angle BETWEEN the two unit arrows.", 24, 52, { color: H.colors.sub, size: 13 });
const lhs = Math.cos(A - B);
const rhs = cA * cB + sA * sB;
const tx = H.W * 0.66, ty = 130, lh = 28;
