H.text("B = " + P.B.toFixed(0) + " deg", tx, ty + lh, { color: H.colors.accent2, size: 14 });
H.text("cosA cosB = " + (cA * cB).toFixed(2), tx, ty + 2.4 * lh, { color: H.colors.sub, size: 13 });
H.text("sinA sinB = " + (sA * sB).toFixed(2), tx, ty + 3.4 * lh, { color: H.colors.sub, size: 13 });
